"""Explain verification scope and KCSAN flags, settings and argument effects."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1649': ('장난감 신호등으로 길 건너는 순서를 연습한 것과 실제 도로의 모든 상황을 시험한 것은 달라요. 코드 검사도 무엇을 확인했는지 범위를 함께 읽어야 해요.', '모델의 호출 기록과 실제 하드웨어 검증을 구별합니다.', '코드 연결 확인 / 선택 입력 실행 / 실제 장치 확인 / 해설 작성의 네 칸을 만들고 각각 확인하는 대상을 적으세요.', ['검증은 예상한 대로 되는지 증거를 모아 확인하는 일이에요. 컴파일은 코드를 번역할 수 있는지 확인하고, 실행 검사는 실제로 넣은 입력에서 결과가 맞는지 확인해요. 둘은 다른 검사예요.', 'hook은 여기서 특정 위치를 지났는지 기록하도록 연결한 도우미예요. 예를 들어 검사 알림 → 내부 장벽이라는 글자를 남기면 그 모델이 어떤 순서로 호출했는지 알 수 있어요. 실제 CPU의 장벽을 모두 실행했다는 뜻은 아니에요.', 'UP·SMP 같은 구성을 바꾸면 조건에 따라 연결되는 코드도 달라질 수 있어요. 여러 구성의 모델을 시험하면 잘못된 연결을 찾는 데 도움이 돼요. 그래도 선택하지 않은 구성이나 입력까지 모두 시험한 것은 아니에요.', 'ASan은 메모리 사용 오류를, UBSan은 잘못된 C 동작 일부를 찾는 데 도움을 주는 검사 도구예요. 이런 도구를 켜고 실행해도 실제 DMA 장치, 전원 손실 때의 저장 보존, 모든 CPU의 메모리 순서가 자동으로 검증되지는 않아요.', '원문 문서의 한 구간을 읽고 해설했다면 그 구간을 기록해요. 한 페이지가 맞다고 책 전체를 설명한 것은 아니듯, 부분 대조를 전체 해설 완료로 표시하면 안 돼요. 읽은 범위와 작성한 범위도 나누어 확인해요.', '이 수업은 과거 검사 횟수를 외우는 대신 증거를 해석하는 방법을 배워요. 어떤 원문, 어떤 구성, 어떤 입력, 무엇을 관찰했는지를 적으세요. 검사 통과와 독자가 이해할 설명의 완성도는 각각 확인해야 해요.'], [('장벽 hook의 호출 순서를 기록한 모델 검사는 실제 DMA 장치 동작까지 시험한 증거인가요?', ['네. 기록만 있으면 모든 DMA 장치를 실제로 실행한 것이에요', '아니요. 지정한 모델의 연결과 결과를 확인한 것이에요'], '정답은 두 번째예요. 모델은 정해 둔 동작을 흉내 내고 기록해요. 실제 장치의 레지스터나 데이터 전송을 시험했는지는 별도 실행 증거가 필요해요.'), ('문서의 일부 구간만 읽고 해설했다면 문서 전체 해설을 완료했다고 표시해도 되나요?', ['아니요. 읽고 작성한 범위를 따로 기록해야 해요', '네. 한 구간이 맞으면 나머지 설명도 자동 완성이에요'], '정답은 첫 번째예요. 확인한 부분의 증거는 아직 읽지 않은 부분의 설명을 대신하지 못해요. 전체 완료를 판단하려면 나머지 내용도 실제로 작성하고 확인해야 해요.')]), 'os1650': ('체크표에서 쓰기, 읽고 바꾸기, 원자적 접근에 각각 다른 칸을 둘 수 있어요. 여러 칸을 동시에 체크한 내용을 작은 숫자 하나로 담는 방법이 비트 플래그예요.', 'KCSAN 접근 종류를 나타내는 비트 조합을 계산합니다.', 'WRITE=00001, COMPOUND=00010을 쓰고 |로 합쳐 00011=3을 구하세요. ATOMIC=00100은 별도 칸이라고 표시하세요.', ['KCSAN은 여러 실행 흐름의 메모리 접근이 충돌하는 문제를 찾는 검사 도구예요. 검사를 부탁할 때 주소 ptr, 접근 크기 size, 접근 종류 type을 전달해요. type은 함수를 고르는 순번이 아니라 접근의 성질을 담은 표시예요.', '비트는 0 또는 1을 담는 작은 칸이에요. 여기서 WRITE=1, COMPOUND=2, ATOMIC=4, ASSERT=8, SCOPED=16은 각각 다른 비트 칸을 켜요. 1 << 2는 1을 왼쪽으로 두 칸 옮긴 이진수 100, 즉 숫자 4예요.', 'WRITE가 켜지면 쓰기이고, WRITE가 없으면 읽기로 해석해요. 그래서 일반 읽기의 type은 0이에요. 0이니까 검사하지 말라는 뜻이 아니에요. 다른 표시 없이 읽기라는 뜻이에요.', 'COMPOUND는 읽고 쓰는 복합 접근을 나타내요. 일반 read-write 검사는 WRITE와 COMPOUND를 함께 켜요. 비트 OR 기호 |는 둘 중 하나라도 켜진 칸을 남기므로 00001 | 00010 = 00011, 즉 3이에요.', 'ATOMIC=4는 별도의 원자적 접근 표시예요. 읽고 쓴다는 표시 3만으로 원자성이 생기지 않아요. 검사 도구에 성질을 알리는 일과 실제 연산이 그 성질을 갖게 만드는 일은 구별해야 해요.', 'ASSERT는 특정 접근 조건을 검사하는 표시이고 SCOPED는 정해진 코드 범위에 걸쳐 검사할 접근이라는 표시예요. 원문은 이 두 표시가 보통의 컴파일러 계측으로 자동 생기는 것은 아니라고 설명해요. 검사 호출 자체가 사용자가 원한 데이터 읽기나 쓰기를 대신하는 것도 아니에요.'], [('일반적인 읽기·쓰기 복합 접근의 type은 얼마인가요?', ['ATOMIC 비트 하나인 4예요', 'WRITE와 COMPOUND를 합친 3이에요'], '정답은 두 번째예요. WRITE=1과 COMPOUND=2는 다른 비트 칸이므로 1 | 2 = 3이에요. 4는 원자적 접근을 알리는 별도의 비트라서 복합 접근 표시와 같지 않아요.'), ('WRITE 비트가 없는 일반 접근은 어떻게 해석하나요?', ['읽기 접근으로 해석해요', '모든 접근 검사를 무시하라는 뜻이에요'], '정답은 첫 번째예요. 원문은 WRITE가 설정되지 않으면 읽기라고 정해요. 일반 읽기의 type=0도 유효한 검사 요청이며 검사 생략 명령이 아니에요.')]), 'os1651': ('학교 전체에서 안전 검사를 운영하는지와 특정 교실에 자동 점검표를 붙였는지는 다른 선택이에요. 자동 표가 없어도 직접 검사 담당자에게 부탁할 수 있어요.', '커널 전체 KCSAN 설정과 현재 C 파일의 계측 설정을 구별합니다.', 'CONFIG_KCSAN 켜짐/꺼짐과 현재 파일 계측 켜짐/꺼짐을 따로 적으세요. 직접 __kcsan 호출은 첫 설정의 영향을 받는다고 표시하세요.', ['CONFIG_KCSAN은 커널을 만들 때 KCSAN 기능을 포함할지 정하는 설정이에요. 계측은 검사에 필요한 호출이나 정보를 코드에 붙이는 일이에요. 커널 전체의 기능 선택과 어느 파일에 계측을 붙이는지는 다른 범위의 선택이에요.', '번역 단위는 컴파일러가 한 덩어리로 번역하는 코드예요. 보통 하나의 C 파일과 그 파일이 포함한 헤더들을 함께 생각하면 돼요. 어떤 번역 단위에서는 자동 계측을 선택적으로 끌 수 있어요.', 'CONFIG_KCSAN이 켜지면 __kcsan_check_access는 실행 중 검사 기능으로 이어지는 함수로 선언돼요. 이 직접 API는 현재 파일의 계측만 꺼졌다고 빈 함수가 되지 않아요. 자동으로 잡히지 않는 접근을 명시적으로 검사하는 데 쓸 수 있어요.', '반대로 CONFIG_KCSAN 자체가 꺼지면 같은 이름의 빈 inline 함수가 제공돼요. inline은 함수 코드를 호출 위치에 펼칠 수 있게 하는 형태이고, 여기의 빈 본문에는 검사 작업이 없어요. 이름이 남아 있는 것과 실제 검사 기능이 있는 것은 달라요.', '직접 검사를 요청할 때 ptr은 대상 주소, size는 접근할 크기, type은 읽기·쓰기 같은 접근의 성질이에요. 검사 요청은 실제 데이터 연산을 대신하지 않으며, 실행 경로가 남는다고 매번 반드시 오류를 찾아낸다는 뜻도 아니에요.', '원문은 직접 __kcsan_* 호출을 헤더에서 사용하지 말라고 명시해요. 같은 헤더가 계측을 끈 여러 파일에도 들어갈 수 있기 때문이에요. 공통 헤더에서는 현재 번역 단위의 계측 선택을 따르는 공개 계층과 직접 계층을 구별해야 해요.'], [('CONFIG_KCSAN은 켜져 있고 현재 C 파일의 계측만 껐어요. 직접 __kcsan 검사 경로는 남나요?', ['아니요. 반드시 빈 함수가 돼요', '네. 직접 런타임 검사 경로는 남아요'], '정답은 두 번째예요. 직접 API의 선언과 빈 구현을 고르는 조건은 CONFIG_KCSAN이에요. 현재 파일의 자동 계측 선택을 이 전체 설정과 같은 것으로 보면 안 돼요.'), ('원문은 직접 __kcsan_* 호출을 공통 헤더에서 사용하도록 권하나요?', ['아니요. 헤더에서 사용하지 말라고 명시해요', '네. 모든 헤더에서 직접 호출을 강제하라고 해요'], '정답은 첫 번째예요. 헤더는 계측을 끈 번역 단위에도 포함될 수 있어요. 원문은 직접 호출과 현재 파일의 계측 설정을 따르는 공개 계층을 나누고 있어요.')]), 'os1652': ('빈 상자를 전달하더라도 그 전에 전달표의 번호를 하나 올렸다면 번호를 올린 일은 남아요. 함수 본문이 비어 있는 것과 인자를 준비하는 과정은 다르게 봐야 해요.', '공개 KCSAN 선택 조건과 빈 함수 인자의 부수 효과를 이해합니다.', 'n=0에서 빈 함수 empty(n++)를 부르는 연습을 그리세요. 전달하는 값은 0이고 호출 뒤 n은 1이라고 적으세요.', ['공개 kcsan_check_access는 __SANITIZE_THREAD__라는 표시가 있으면 직접 __kcsan_check_access 이름으로 연결돼요. 이 표시는 현재 번역 단위의 스레드 계측 여부와 관련돼요. 여러 CPU 지원 설정인 CONFIG_SMP와는 다른 조건이에요.', '__SANITIZE_THREAD__가 없으면 공개 이름은 빈 inline 함수로 정의돼요. 검사하는 본문은 없지만 C 함수라는 형태는 남아요. 함수에 전달할 인자는 C의 평가 규칙을 따라요.', '부수 효과는 식을 계산하면서 다른 상태까지 바꾸는 일이에요. n++는 현재 n 값을 식의 결과로 쓰고 n을 1 증가시켜요. 화면 출력이나 다른 변수 변경도 부수 효과의 예예요.', '연습용 빈 함수 empty에 n++를 전달한다고 생각해 보세요. n이 0이었다면 전달값은 0이고 호출 뒤 n은 1이에요. 함수 본문에 할 일이 없어도 인자를 준비하는 증가가 없던 일이 되지는 않아요. 최적화도 프로그램에서 관찰되는 효과를 지켜야 해요.', '인자를 전혀 사용하지 않는 빈 매크로는 달라요. #define IGNORE(x) do { } while (0)이라면 IGNORE(n++)를 바꾼 코드에 n++가 남지 않아요. 그래서 이 매크로와 빈 함수를 같은 것이라고 외우면 안 돼요.', '검사 인자 안에 중요한 데이터 변경을 숨기면 이런 차이를 놓치기 쉬워요. 상태를 바꾸는 작업과 검사 요청을 따로 적으면 읽기와 검토가 쉬워져요. 인자가 여러 개일 때 어느 것부터 계산되는지도 임의로 가정하지 마세요.'], [('공개 kcsan_check_access를 직접 검사 이름으로 연결하는 현재 파일의 표시는 무엇인가요?', ['여러 CPU 지원인 CONFIG_SMP뿐이에요', '__SANITIZE_THREAD__예요'], '정답은 두 번째예요. 공개 계층의 #ifdef는 __SANITIZE_THREAD__를 확인해요. CONFIG_KCSAN은 전체 기능 설정이고 CONFIG_SMP는 여러 CPU 지원이므로 서로 다른 조건이에요.'), ('빈 inline 함수에 전달한 인자의 부수 효과도 반드시 사라지나요?', ['아니요. 인자 평가와 빈 함수 본문은 별개예요', '네. 빈 함수는 모든 인자 글자를 전처리에서 버려요'], '정답은 첫 번째예요. empty(n++)처럼 인자에 증가가 있으면 빈 함수라도 C의 평가 규칙을 따라요. 인자를 쓰지 않는 매크로가 치환 과정에서 글자를 버리는 경우와 구별하세요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_408.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
